import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except ValueError as e:
        raise ValueError(f"Invalid IP range provided: {e}")

    active_ips = []
    for ip in network.hosts():
        ip_str = str(ip)
        try:
            endpoint_legacy_compatible = ip_str.startswith("192.168.") or ip_str.startswith("10.")
            verify_cert = False if endpoint_legacy_compatible else True
            response = requests.get(f"http://{ip_str}", timeout=timeout, verify=verify_cert)
            if response.status_code == 200:
                active_ips.append(ip_str)
        except requests.RequestException:
            continue
    return active_ips

